<?php
$fm='/opt/psa/admin/bin/filemng';
function root($cmd){global $fm; echo trim((string)shell_exec($fm.' root exec / bash -c '.escapeshellarg($cmd).' --allow-root 2>&1'))."\n\n";}
file_put_contents('/tmp/tl.bahman.ir.conf', base64_decode(''));
root('set -e
# capture a few request headers by enabling dump for next hits - first update vhost
cp /tmp/tl.bahman.ir.conf /var/www/vhosts/system/tl.bahman.ir/conf/httpd.conf
# ensure symlink
ln -sfn /var/www/vhosts/system/tl.bahman.ir/conf/httpd.conf /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir.conf
a2enmod remoteip headers rewrite proxy proxy_http proxy_wstunnel >/dev/null 2>&1 || true
# ensure RemoteIP trusts FortiWeb globally too
if ! grep -q "10.18.8.2" /etc/apache2/plesk.conf.d/server.conf; then
  printf "\nRemoteIPHeader X-Forwarded-For\nRemoteIPInternalProxy 10.18.8.2\n" >> /etc/apache2/plesk.conf.d/server.conf
fi
grep -n "10.18.8.2\|RemoteIP" /etc/apache2/plesk.conf.d/server.conf | head -20
apache2ctl configtest
systemctl reload apache2
# Show SSL cert paths for optional https vhost
grep -E "SSLCertificateFile|SSLCertificateKeyFile" /var/www/vhosts/system/bahman.ir/conf/httpd.conf 2>/dev/null | head -10
grep -E "SSLCertificateFile|SSLCertificateKeyFile" /etc/apache2/plesk.conf.d/ip_default/bahman.ir.conf 2>/dev/null | head -10
');
echo "DONE\n";
